import React, { useState } from 'react';
import { Sliders } from 'lucide-react';

interface BeforeAfterSliderProps {
  beforeImage: string;
  afterImage: string;
  beforeLabel?: string;
  afterLabel?: string;
  title: string;
  subtitle: string;
}

export const BeforeAfterSlider: React.FC<BeforeAfterSliderProps> = ({
  beforeImage,
  afterImage,
  beforeLabel = 'Legacy Interface (Before)',
  afterLabel = 'DREAM Architecture (After)',
  title,
  subtitle,
}) => {
  const [sliderPos, setSliderPos] = useState(50);

  return (
    <div data-ut-variant="before-after:case-study" className="w-full">
      <div className="mb-6 flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <div className="flex items-center gap-2 text-primary font-mono text-xs uppercase tracking-widest mb-2">
            <Sliders className="w-4 h-4" />
            <span>Interactive Craft Proof</span>
          </div>
          <h2 className="text-2xl sm:text-3xl font-heading font-[number:var(--ut-weight-display)] uppercase text-foreground">
            {title}
          </h2>
        </div>
        <p className="text-sm text-muted-foreground max-w-md">
          {subtitle}
        </p>
      </div>

      <div className="relative w-full aspect-[16/9] sm:aspect-[21/9] rounded-lg overflow-hidden border border-border bg-card shadow-2xl select-none group">
        {/* After Image (Background) */}
        <img
          src={afterImage}
          alt={afterLabel}
          className="absolute inset-0 w-full h-full object-cover object-left"
        />
        <div className="absolute top-4 right-4 bg-primary text-primary-foreground font-mono text-[10px] sm:text-xs font-bold px-3 py-1 rounded shadow-md uppercase tracking-wider z-10">
          {afterLabel}
        </div>

        {/* Before Image (Clipped Overlay) */}
        <div
          className="absolute inset-0 overflow-hidden"
          style={{ width: `${sliderPos}%` }}
        >
          <img
            src={beforeImage}
            alt={beforeLabel}
            className="absolute inset-0 w-full h-full object-cover object-left max-w-none"
            style={{ width: '100%', height: '100%' }}
          />
          <div className="absolute top-4 left-4 bg-muted/90 text-muted-foreground border border-border font-mono text-[10px] sm:text-xs font-bold px-3 py-1 rounded shadow-md uppercase tracking-wider z-10">
            {beforeLabel}
          </div>
        </div>

        {/* Divider Bar */}
        <div
          className="absolute top-0 bottom-0 w-1 bg-primary cursor-ew-resize z-20"
          style={{ left: `${sliderPos}%` }}
        >
          <div className="absolute top-1/2 -translate-y-1/2 -translate-x-1/2 w-8 h-8 rounded-full bg-primary text-primary-foreground border-2 border-background flex items-center justify-center shadow-lg">
            <Sliders className="w-4 h-4" />
          </div>
        </div>

        {/* Native Range Slider */}
        <input
          type="range"
          min="0"
          max="100"
          value={sliderPos}
          onChange={(e) => setSliderPos(Number(e.target.value))}
          className="absolute inset-0 w-full h-full opacity-0 cursor-ew-resize z-30"
          aria-label="Drag to compare before and after interface designs"
        />
      </div>

      <div className="mt-4 flex items-center justify-between text-xs text-muted-foreground font-mono">
        <span>◀ Drag handle to compare product transformation</span>
        <span className="text-primary font-bold">100% Bespoke Design Systems</span>
      </div>
    </div>
  );
};
export default BeforeAfterSlider;

