import React, { useState, useEffect } from 'react';
import * as Dialog from '@/unison/ui/radix/dialog';
import { X, Sparkles, Send, CheckCircle2, Calendar, Clock } from '@/unison/ui/icons';
import { DayPicker } from 'react-day-picker';
import 'react-day-picker/dist/style.css';

export interface ConsultationModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit?: (formData: any) => void;
  preselectedProjectName?: string;
  isSubmitted?: boolean;
  onReset?: () => void;
}

export const ConsultationModal: React.FC<ConsultationModalProps> = ({
  isOpen,
  onClose,
  onSubmit,
  preselectedProjectName = '',
  isSubmitted,
  onReset,
}) => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    focus: preselectedProjectName || 'UI/UX Architecture',
  });
  const [selectedDate, setSelectedDate] = useState<Date | undefined>();
  const [selectedTime, setSelectedTime] = useState<string>('');

  useEffect(() => {
    if (preselectedProjectName) {
      setFormData((prev) => ({ ...prev, focus: preselectedProjectName }));
    }
  }, [preselectedProjectName]);

  useEffect(() => {
    if (isOpen && !isSubmitted) {
        setFormData({
            name: '',
            email: '',
            focus: preselectedProjectName || 'UI/UX Architecture',
        });
        setSelectedDate(undefined);
        setSelectedTime('');
    }
  }, [isOpen, isSubmitted, preselectedProjectName]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (onSubmit && selectedDate && selectedTime) {
      onSubmit({ ...formData, date: selectedDate.toLocaleDateString(), time: selectedTime });
    }
  };

  const handleReset = () => {
    if (onReset) onReset();
  }

  const availableTimes = ['09:00 AM', '10:00 AM', '11:00 AM', '02:00 PM', '03:00 PM', '04:00 PM'];
  const today = new Date();

  return (
    <Dialog.Root open={isOpen} onOpenChange={onClose}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 bg-background/80 backdrop-blur-sm z-50 animate-fade-in-up" />
        <Dialog.Content
          onEscapeKeyDown={onClose}
          className="fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-50 w-[90vw] max-w-4xl max-h-[85vh] bg-card border border-border rounded-lg shadow-2xl flex flex-col overflow-hidden"
        >
          <div className="relative h-full w-full animate-fade-in-up p-6 sm:p-8 overflow-y-auto">
            <Dialog.Close asChild>
              <button
                type="button"
                onClick={onClose}
                className="absolute top-4 right-4 p-2 rounded-full text-muted-foreground hover:bg-muted hover:text-foreground transition-colors z-10"
                aria-label="Close"
              >
                <X className="w-5 h-5" />
              </button>
            </Dialog.Close>

              {isSubmitted ? (
                <div className="text-center py-12 flex flex-col items-center justify-center h-full">
                  <CheckCircle2 className="w-16 h-16 text-primary mb-6" />
                  <h2 className="text-2xl font-heading text-foreground mb-2">Consultation Booked!</h2>
                  <p className="text-muted-foreground max-w-md mx-auto mb-8">
                    Thank you for scheduling a session. We've sent a confirmation and a calendar invite to your email. We look forward to speaking with you.
                  </p>
                  <button
                    type="button"
                    onClick={handleReset}
                    className="btn-secondary py-2 px-6 text-sm"
                  >
                    Book Another
                  </button>
                </div>
              ) : (
                <div>
                  <Dialog.Title className="text-2xl sm:text-3xl font-heading uppercase tracking-tight text-foreground mb-1">
                    Schedule Strategic Consultation
                  </Dialog.Title>
                  <Dialog.Description className="text-muted-foreground mb-8">
                    Select a date and time, then provide your details to book a 30-minute session.
                  </Dialog.Description>

                  <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                    {/* Left Column: Calendar & Time */}
                    <div className="space-y-6">
                      <div>
                        <h3 className="text-sm font-[number:var(--ut-weight-display)] uppercase tracking-wider text-primary mb-3 flex items-center gap-2">
                          <Calendar className="w-4 h-4" />
                          <span>1. Select a Date</span>
                        </h3>
                        <div className="bg-background/50 border border-border rounded-md p-1">
                           <style>{`
                              .rdp { --rdp-cell-size: 40px; --rdp-accent-color: hsl(var(--primary)); --rdp-background-color: hsl(var(--muted)); color: hsl(var(--foreground)); }
                              .rdp-day_selected, .rdp-day_selected:hover { background-color: hsl(var(--primary)) !important; color: hsl(var(--primary-foreground)) !important; }
                              .rdp-button:hover:not([disabled]):not(.rdp-day_selected) { background-color: hsl(var(--muted)); }
                              .rdp-nav_button { color: hsl(var(--foreground)) !important; }
                              .rdp-head_cell { color: hsl(var(--muted-foreground)); }
                              .rdp-caption_label { color: hsl(var(--foreground)); }
                              .rdp-day_today { font-weight: bold; color: hsl(var(--primary)) !important; }
                           `}</style>
                          <DayPicker
                            mode="single"
                            selected={selectedDate}
                            onSelect={setSelectedDate}
                            disabled={{ before: today }}
                            fromMonth={today}
                            className="text-sm"
                          />
                        </div>
                      </div>
                      {selectedDate && (
                        <div className="animate-fade-in-up">
                          <h3 className="text-sm font-[number:var(--ut-weight-display)] uppercase tracking-wider text-primary mb-3 flex items-center gap-2">
                            <Clock className="w-4 h-4" />
                            <span>2. Select a Time</span>
                          </h3>
                          <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                            {availableTimes.map((time) => (
                              <button
                                key={time}
                                type="button"
                                onClick={() => setSelectedTime(time)}
                                className={`px-3 py-2 text-xs rounded-md border text-center transition-colors ${
                                  selectedTime === time
                                    ? 'bg-primary border-primary text-primary-foreground font-bold'
                                    : 'bg-muted border-border text-muted-foreground hover:bg-border hover:text-foreground'
                                }`}
                              >
                                {time}
                              </button>
                            ))}
                          </div>
                        </div>
                      )}
                    </div>

                    {/* Right Column: Form */}
                    <div className={`transition-opacity duration-500 ${selectedDate && selectedTime ? 'opacity-100' : 'opacity-40 pointer-events-none'}`}>
                       <h3 className="text-sm font-[number:var(--ut-weight-display)] uppercase tracking-wider text-primary mb-3 flex items-center gap-2">
                          <Sparkles className="w-4 h-4" />
                          <span>3. Your Details</span>
                        </h3>
                      <form onSubmit={handleSubmit} className="space-y-4">
                        <div>
                          <label htmlFor="name" className="block text-xs font-medium text-muted-foreground mb-1">Your Name *</label>
                          <input type="text" id="name" required value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} className="ut-shadcn-input" />
                        </div>
                        <div>
                          <label htmlFor="email" className="block text-xs font-medium text-muted-foreground mb-1">Work Email *</label>
                          <input type="email" id="email" required value={formData.email} onChange={(e) => setFormData({ ...formData, email: e.target.value })} className="ut-shadcn-input" />
                        </div>
                        <div>
                          <label htmlFor="focus" className="block text-xs font-medium text-muted-foreground mb-1">Project Focus</label>
                          <select id="focus" value={formData.focus} onChange={(e) => setFormData({ ...formData, focus: e.target.value })} className="ut-shadcn-input appearance-none">
                              <option>UI/UX Architecture</option>
                              <option>Design System</option>
                              <option>Mobile App Redesign</option>
                              <option>SaaS Platform Design</option>
                              <option>General Consultation</option>
                          </select>
                        </div>
                        <button type="submit" data-ut-intent="contact.submit" className="w-full btn-primary py-3 justify-center text-sm font-bold uppercase tracking-wider mt-4" disabled={!selectedDate || !selectedTime || !formData.name || !formData.email}>
                          <Send className="w-4 h-4" />
                          <span>Book 30-Min Session</span>
                        </button>
                        <p className="text-xs text-muted-foreground text-center">Your information is confidential and will not be shared.</p>
                      </form>
                    </div>
                  </div>
                </div>
              )}
            </div>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
};

export default ConsultationModal;

